<?php $editing=(bool)$category;$old=App\Core\Session::get('_old',[]);$value=static fn($key,$default='')=>$old[$key]??($category[$key]??$default); ?>
<section class="page-head"><div><a class="back-link" href="/categories">← Categories</a><h1><?= $editing?'Edit category':'Add category' ?></h1><p class="muted">Keep names short and easy to scan on a phone.</p></div></section><form method="post" action="<?= $editing?'/categories/'.e($category['id']):'/categories' ?>" enctype="multipart/form-data" class="editor-layout"><?= csrf_field() ?><section class="panel form-section"><div class="section-heading"><span>01</span><div><h2>Category details</h2><p>Name and describe this product group.</p></div></div><div class="form-stack"><label>Name<input name="name" value="<?= e($value('name')) ?>" maxlength="100" required data-slug-source></label><label>Store address<input name="slug" value="<?= e($value('slug')) ?>" maxlength="100" placeholder="generated-from-name" data-slug-target><small>Lowercase letters, numbers, and hyphens.</small></label><label>Description <span class="optional">Optional</span><textarea name="description" maxlength="500" rows="4"><?= e($value('description')) ?></textarea></label><label>Status<select name="status"><option value="ACTIVE" <?= $value('status','ACTIVE')==='ACTIVE'?'selected':'' ?>>Active</option><option value="INACTIVE" <?= $value('status')==='INACTIVE'?'selected':'' ?>>Hidden</option></select></label><label>Category image <span class="optional">Optional</span><?php if($editing&&$category['image_path']):?><img class="category-image-preview" src="<?= e($category['image_path']) ?>" alt="Current category image"><span class="check-row"><input type="checkbox" name="remove_image" value="1"><span>Remove current image</span></span><?php endif ?><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG, or WebP · maximum 5 MB.</small></label></div></section><aside class="editor-actions panel"><strong><?= $editing?'Save category':'Create category' ?></strong><p>Active categories can appear on the future public storefront.</p><button class="button primary" type="submit"><?= $editing?'Save changes':'Create category' ?></button><a class="button secondary" href="/categories">Cancel</a></aside></form>
